/// Validate one RFC 7662 answer for `resource` and `issuer` at unix time `now`.
pub fn grant_from_introspection(
    body: &Value,
    resource: &str,
    issuer: &str,
    now: i64,
) -> Result<Grant, Rejection> {
    let obj = body.as_object().ok_or(Rejection::Malformed)?;
    if obj.get("active").and_then(Value::as_bool) != Some(true) {
        return Err(Rejection::Inactive);
    }
    let str_of = |k: &str| obj.get(k).and_then(Value::as_str).unwrap_or("");
    let aud_ok = match obj.get("aud") {
        Some(Value::String(s)) => s == resource,
        Some(Value::Array(a)) => a.iter().any(|v| v.as_str() == Some(resource)),
        _ => false,
    };
    if !aud_ok {
        return Err(Rejection::Audience);
    }
    if str_of("iss") != issuer {
        return Err(Rejection::Issuer);
    }
    if !str_of("token_type").eq_ignore_ascii_case("bearer") {
        return Err(Rejection::TokenType);
    }
    let exp = obj.get("exp").and_then(Value::as_i64).unwrap_or(0);
    if exp <= now {
        return Err(Rejection::Expired);
    }
    let sub = str_of("sub");
    if sub.is_empty() {
        return Err(Rejection::Subject);
    }
    Ok(Grant {
        subject: sub.to_string(),
        client_id: str_of("client_id").to_string(),
        scopes: str_of("scope")
            .split_whitespace()
            .map(String::from)
            .collect(),
        expires_at: exp,
        issued_at: obj.get("iat").and_then(Value::as_i64).unwrap_or(0),
    })
}

/// A refused request, ready to send: status, `WWW-Authenticate`, JSON body.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Challenge {
    kind: Kind,
    metadata_url: String,
    scope: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Kind {
    NoCredentials,
    InvalidToken(&'static str),
    InvalidRequest,
    InsufficientScope(Vec<String>),
    Unavailable,
}

/// Remove characters that would break a quoted-string attribute value.
fn clean(v: &str) -> String {
    v.chars()
        .filter(|c| *c != '"' && *c != '\\' && !c.is_control())
        .collect()
}

impl Challenge {
    /// The HTTP status: 401, 400, 403 or 503.
    pub fn status(&self) -> u16 {
        match self.kind {
            Kind::NoCredentials | Kind::InvalidToken(_) => 401,
            Kind::InvalidRequest => 400,
            Kind::InsufficientScope(_) => 403,
            Kind::Unavailable => 503,
        }
    }

    /// The `WWW-Authenticate` value (empty for a 503, which carries none).
    pub fn www_authenticate(&self) -> String {
        let meta = format!("resource_metadata=\"{}\"", clean(&self.metadata_url));
        let scope = if self.scope.is_empty() {
            String::new()
        } else {
            format!(", scope=\"{}\"", clean(&self.scope))
        };
        match &self.kind {
            Kind::NoCredentials => format!("Bearer {meta}{scope}"),
            Kind::InvalidToken(d) => {
                format!("Bearer error=\"invalid_token\", error_description=\"{}\", {meta}{scope}", clean(d))
            }
            Kind::InvalidRequest => format!(
                "Bearer error=\"invalid_request\", error_description=\"malformed Authorization header\", {meta}"
            ),
            Kind::InsufficientScope(needed) => format!(
                "Bearer error=\"insufficient_scope\", scope=\"{}\", {meta}",
                clean(&needed.join(" "))
            ),
            Kind::Unavailable => String::new(),
        }
    }

    /// The full HTTP answer.
    pub fn reply(&self) -> Reply {
        let (error, description) = match &self.kind {
            Kind::NoCredentials => ("invalid_request", "authentication required"),
            Kind::InvalidToken(d) => ("invalid_token", *d),
            Kind::InvalidRequest => ("invalid_request", "malformed Authorization header"),
            Kind::InsufficientScope(_) => (
                "insufficient_scope",
                "the token lacks a scope this operation needs",
            ),
            Kind::Unavailable => ("temporarily_unavailable", ""),
        };
        let body = if self.kind == Kind::Unavailable {
            json!({ "error": error })
        } else {
            json!({ "error": error, "error_description": description })
        };
        let mut headers = vec![("content-type".to_string(), "application/json".to_string())];
        if self.kind == Kind::Unavailable {
            headers.push(("retry-after".into(), "5".into()));
        } else {
            headers.push(("www-authenticate".into(), self.www_authenticate()));
        }
        Reply {
            status: self.status(),
            headers,
            body: body.to_string(),
        }
    }
}

